const charts = new WeakMap();

jaspring.hooks.register('chart', {
  mounted(el, ctx) {
    charts.set(el, new Chart(el, {
      type: 'bar',
      data: {
        labels: ctx.params.labels,
        datasets: [{ label: 'Sales', data: ctx.params.values }]
      },
      options: {
        maintainAspectRatio: false,
        onClick: (_, bars) => bars.length && ctx.pushEvent('bar-picked', { index: bars[0].index })
      }
    }));
  },
  updated(el, ctx) {
    const chart = charts.get(el);
    chart.data.labels = ctx.params.labels;
    chart.data.datasets[0].data = ctx.params.values;
    chart.resize();
    chart.update();
  },
  destroyed(el) {
    charts.get(el)?.destroy();
    charts.delete(el);
  },
  total(el) {
    return charts.get(el).data.datasets[0].data.reduce((sum, value) => sum + value, 0);
  }
});

