@Component(selector = "app-theme", templateUrl = "theme.component.html")
public class ThemeComponent implements OnInit {
    public final WritableSignal<String> theme = Signals.signal("light");

    @Override
    public void ngOnInit() {
        Platform.onBrowser(client -> client.localStorage().get("theme").orElse("light"))
                .thenAccept(theme::set);
    }

    public void toggle() {
        final var next = theme.get().equals("dark") ? "light" : "dark";
        Platform.onBrowser(client -> {
            client.localStorage().set("theme", next);
            return next;
        }).thenAccept(theme::set);
    }
}

public void locate() {
    Platform.onBrowserAsync(Position.class, client -> client.geolocation().current())
            .whenComplete((position, error) -> where.set(error == null
                    ? position.latitude() + ", " + position.longitude()
                    : "Location unavailable"));
}

public void copy() {
    final var text = where.get();
    Platform.onBrowserAsync(Void.class, client -> client.clipboard().writeText(text))
            .whenComplete((ignored, error) -> status.set(error == null ? "copied" : "copy failed"));
}

public record Draft(String title, List<String> tags) {}

public void saveDraft() {
    final var draft = new Draft(title.get(), tags.get());   // copy state into a local
    Platform.onBrowser(client -> {
        client.sessionStorage().set("draft-title", draft.title());
        return draft.tags().size();
    }).thenAccept(count -> status.set("Saved with " + count + " tags"));
}

public void toggleTheme() {
    final var next = "dark".equals(theme.get()) ? "light" : "dark";
    Platform.onBrowser(client -> {
        client.localStorage().set("theme", next);
        client.host().toggleClass("dark", "dark".equals(next));
        client.host().dispatch("theme-changed", next);
        return next;
    }).thenAccept(theme::set);
}

